import java.util.Arrays;
public class Main {
    static int find(int[] parent, int x) { if (parent[x] != x) parent[x] = find(parent, parent[x]); return parent[x]; }
    static void union(int[] parent, int a, int b) { parent[find(parent, a)] = find(parent, b); }
    public static void main(String[] args) {
        int[] parent = {0, 1, 2, 3};
        union(parent, 0, 1); union(parent, 2, 3); union(parent, 1, 2);
        System.out.println((find(parent, 0) == find(parent, 3)) + " " + Arrays.toString(parent));
    }
}
